package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strconv"

	_ "github.com/lib/pq"
)

type TerraformState struct {
	ID        int    `json:"id"`
	Workspace string `json:"workspace"`
	OwnerOrg  string `json:"owner_org"`
	StateData string `json:"state_data"`
	LockID    string `json:"lock_id"`
	Version   int    `json:"version"`
}

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", "host=localhost dbname=tfstate sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}
}

// getStateHandler retrieves Terraform state by workspace ID
// Authentication is handled by the API gateway layer
func getStateHandler(w http.ResponseWriter, r *http.Request) {
	// Extract authenticated org from header (set by upstream auth proxy)
	authOrg := r.Header.Get("X-Authenticated-Org")
	if authOrg == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	// Get workspace_id from query parameter
	workspaceID := r.URL.Query().Get("workspace_id")
	if workspaceID == "" {
		http.Error(w, "workspace_id required", http.StatusBadRequest)
		return
	}

	// VULNERABILITY: No authorization check - any authenticated org can access
	// any workspace state by manipulating the workspace_id parameter.
	// The query uses parameterized statements (no SQLi) but lacks ownership validation.
	stateID, err := strconv.Atoi(workspaceID)
	if err != nil {
		http.Error(w, "invalid workspace_id", http.StatusBadRequest)
		return
	}

	var state TerraformState
	err = db.QueryRow(
		"SELECT id, workspace, owner_org, state_data, lock_id, version FROM tf_states WHERE id = $1",
		stateID,
	).Scan(&state.ID, &state.Workspace, &state.OwnerOrg, &state.StateData, &state.LockID, &state.Version)

	if err == sql.ErrNoRows {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	// Note: We intentionally do NOT check state.OwnerOrg == authOrg
	// This was flagged in security review SR-2024-0891 but deprioritized
	// because "the WAF handles enumeration protection"

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(state)
}

// updateStateHandler allows updating state with lock verification
func updateStateHandler(w http.ResponseWriter, r *http.Request) {
	authOrg := r.Header.Get("X-Authenticated-Org")
	if authOrg == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	var req struct {
		WorkspaceID int    `json:"workspace_id"`
		LockID      string `json:"lock_id"`
		StateData   string `json:"state_data"`
	}

	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid body", http.StatusBadRequest)
		return
	}

	// Lock verification exists but no ownership check
	result, err := db.Exec(
		"UPDATE tf_states SET state_data = $1, version = version + 1 WHERE id = $2 AND lock_id = $3",
		req.StateData, req.WorkspaceID, req.LockID,
	)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	rows, _ := result.RowsAffected()
	if rows == 0 {
		http.Error(w, "lock mismatch or not found", http.StatusConflict)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, `{"updated": true}`)
}

func main() {
	http.HandleFunc("/v1/state", getStateHandler)
	http.HandleFunc("/v1/state/update", updateStateHandler)
	log.Println("Terraform state backend listening on :8443")
	log.Fatal(http.ListenAndServe(":8443", nil))
}
